284	    public function integrationForProvider(string $provider): ?ProfessionalIntegration
285	    {
286	        $provider = mb_strtolower(trim($provider));
287	
288	        if ($provider === '') {
289	            return null;
290	        }
291	
292	        if ($this->relationLoaded('integrations')) {
293	            return $this->integrations->firstWhere('provider', $provider);
294	        }
295	
296	        return $this->integrations()->where('provider', $provider)->first();
297	    }
