79	    return new;
80	  end if;
81	
82	  select exists (
83	    select 1
84	    from core.comet_staff cs
85	    where cs.auth_user_id = uid
86	      and cs.role = 'admin'
87	  ) into is_admin;
88	
89	  if not is_admin then
90	    if new.role is distinct from old.role then
91	      raise exception 'Only admins can change staff role';
92	    end if;
93	
94	    if new.auth_user_id is distinct from old.auth_user_id then
95	      raise exception 'Only admins can change auth_user_id';
96	    end if;
97	  end if;
98	
99	  return new;
100	end;
