130	-- Enforce max 6 gallery media per site
131	CREATE OR REPLACE FUNCTION core.enforce_site_gallery_max6()
132	RETURNS trigger
133	LANGUAGE plpgsql
134	SET search_path TO 'pg_catalog'
135	AS $$
136	declare
137	  cnt int;
138	begin
139	  if new.deleted_at is not null then
140	    return new;
141	  end if;
142	
143	  if tg_op = 'UPDATE' then
144	    if old.site_id = new.site_id and old.deleted_at is null and new.deleted_at is null then
145	      return new;
146	    end if;
147	  end if;
148	
149	  select count(*)
150	    into cnt
151	  from site.site_media si
152	  where si.site_id = new.site_id
153	    and si.deleted_at is null
154	    and (tg_op <> 'UPDATE' or si.id <> new.id);
155	
156	  if cnt >= 6 then
157	    raise exception 'Gallery limit reached: max 6 images per site';
158	  end if;
159	
160	  return new;
161	end;
162	$$;
